/* @lc app=leetcode id=3957 lang=kotlin */ class Solution { fun run(P: LongArray, l: Int, r: Int, lam: Long): Long = java.util.ArrayDeque<Int>().let { dq -> LongArray(P.size).let { e -> (1 until P.size).forEach { i -> (if (i - l >= 0) (e[i - l] - P[i - l] * 131072L).let { v -> generateSequence { dq.peekLast()?.takeIf { e[it] - P[it] * 131072L <= v } }.forEach { _ -> dq.pollLast() }.let { dq.addLast(i - l) } } else Unit).let { generateSequence { dq.peekFirst()?.takeIf { it < i - r } }.forEach { _ -> dq.pollFirst() }.let { e[i] = maxOf(e[i - 1], dq.peekFirst()?.let { e[it] - P[it] * 131072L + P[i] * 131072L - lam * 131072L - 1 } ?: Long.MIN_VALUE) } } }.let { e[P.size - 1] } } } fun single(P: LongArray, l: Int, r: Int): Long = java.util.ArrayDeque<Int>().let { dq -> (l until P.size).maxOf { i -> P[i - l].let { v -> generateSequence { dq.peekLast()?.takeIf { P[it] >= v } }.forEach { _ -> dq.pollLast() }.let { dq.addLast(i - l) } }.let { generateSequence { dq.peekFirst()?.takeIf { it < i - r } }.forEach { _ -> dq.pollFirst() } }.let { P[i] - P[dq.peekFirst()!!] } } } fun dec(e: Long): Long = (e + 131071L) shr 17 fun maximumSum(nums: IntArray, m: Int, l: Int, r: Int): Long = nums.runningFold(0L) { a, b -> a + b }.toLongArray().let { P -> run(P, l, r, 0L).let { e0 -> (dec(e0) * 131072L - e0).let { c0 -> if (c0 == 0L) single(P, l, r) else if (c0 <= m) dec(e0) else generateSequence(1L to 20_000_000_001L) { (lo, hi) -> ((lo + hi) / 2).let { mid -> run(P, l, r, mid).let { e -> if (dec(e) * 131072L - e <= m) lo to mid else mid + 1 to hi } } }.first { it.first >= it.second }.first.let { lam -> dec(run(P, l, r, lam)) + lam * m } } } } }